(PKG / 'universal_market_adapter_replay_contracts.py').write_text('"""\nCanonical ReplayResult contract shared by OI-192 through OI-196.\n"""\nfrom __future__ import annotations\nfrom dataclasses import dataclass, field, asdict\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nfrom typing import Any, Dict, List, Mapping\nimport json\n\nREAD_ONLY_GUARDRAILS = {\n    "oracle_read_only": True,\n    "executes_trades": False,\n    "routes_orders": False,\n    "submits_orders": False,\n    "manages_positions": False,\n    "execution_owner": "Q_SERIES_ONLY",\n}\n\ndef utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\ndef stable_json(value: Any) -> str:\n    return json.dumps(value, sort_keys=True, separators=(",", ":"), default=str)\n\ndef stable_hash(value: Any) -> str:\n    return sha256(stable_json(value).encode("utf-8")).hexdigest()\n\ndef safe_dict(value: Any) -> Dict[str, Any]:\n    if value is None:\n        return {}\n    if isinstance(value, Mapping):\n        return dict(value)\n    if hasattr(value, "to_dict"):\n        converted = value.to_dict()\n        if isinstance(converted, Mapping):\n            return dict(converted)\n    if hasattr(value, "__dict__"):\n        return dict(value.__dict__)\n    return {"value": value}\n\ndef safe_records(value: Any) -> List[Dict[str, Any]]:\n    if value is None:\n        return []\n    if isinstance(value, ReplayResult):\n        return list(value.records)\n    if isinstance(value, list):\n        return [safe_dict(item) for item in value]\n    data = safe_dict(value)\n    for key in ("records", "results", "items"):\n        if isinstance(data.get(key), list):\n            return [safe_dict(item) for item in data[key]]\n    return []\n\n@dataclass(frozen=True)\nclass ReplayDecision:\n    record_id: str\n    included: bool\n    reasons: List[str] = field(default_factory=list)\n    rejected_by: List[str] = field(default_factory=list)\n    evidence: Dict[str, Any] = field(default_factory=dict)\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n@dataclass(frozen=True)\nclass ReplayResult:\n    result_id: str\n    created_at: str\n    oracle_instance_id: str\n    module_id: str\n    module_name: str\n    operation: str\n    passed: bool\n    input_count: int\n    output_count: int\n    records: List[Dict[str, Any]]\n    criteria: Dict[str, Any] = field(default_factory=dict)\n    decisions: List[ReplayDecision] = field(default_factory=list)\n    metrics: Dict[str, Any] = field(default_factory=dict)\n    insights: List[Dict[str, Any]] = field(default_factory=list)\n    result_hash: str = ""\n    read_only_guardrails: Dict[str, Any] = field(default_factory=lambda: dict(READ_ONLY_GUARDRAILS))\n    telemetry: Dict[str, Any] = field(default_factory=dict)\n    explainability: Dict[str, Any] = field(default_factory=dict)\n\n    @property\n    def results(self) -> List[Dict[str, Any]]:\n        return list(self.records)\n\n    @property\n    def record_count(self) -> int:\n        return len(self.records)\n\n    @property\n    def status(self) -> str:\n        return "passed" if self.passed else "failed"\n\n    def to_dict(self) -> Dict[str, Any]:\n        data = asdict(self)\n        data["results"] = list(self.records)\n        data["record_count"] = len(self.records)\n        data["status"] = self.status\n        return data\n\ndef make_replay_result(\n    *,\n    oracle_instance_id: str,\n    module_id: str,\n    module_name: str,\n    operation: str,\n    records: Any,\n    input_count: int | None = None,\n    criteria: Mapping[str, Any] | None = None,\n    decisions: List[ReplayDecision] | None = None,\n    metrics: Mapping[str, Any] | None = None,\n    insights: List[Mapping[str, Any]] | None = None,\n    passed: bool = True,\n    explainability: Mapping[str, Any] | None = None,\n) -> ReplayResult:\n    normalized_records = safe_records(records)\n    normalized_criteria = safe_dict(criteria)\n    normalized_metrics = safe_dict(metrics)\n    normalized_insights = [safe_dict(item) for item in (insights or [])]\n    normalized_decisions = list(decisions or [])\n    result_input_count = len(normalized_records) if input_count is None else int(input_count)\n    payload = {\n        "oracle_instance_id": oracle_instance_id,\n        "module_id": module_id,\n        "operation": operation,\n        "records": normalized_records,\n        "criteria": normalized_criteria,\n        "metrics": normalized_metrics,\n        "insights": normalized_insights,\n        "passed": passed,\n    }\n    result_hash = stable_hash(payload)\n    telemetry = {\n        "module_id": module_id,\n        "module_name": module_name,\n        "oracle_instance_id": oracle_instance_id,\n        "operation": operation,\n        "input_count": result_input_count,\n        "output_count": len(normalized_records),\n        "criteria_hash": stable_hash(normalized_criteria),\n        "result_hash": result_hash,\n        "read_only": True,\n    }\n    return ReplayResult(\n        result_id=f"{module_id.lower().replace(\'-\', \'\')}.result.{result_hash[:24]}",\n        created_at=utc_now(),\n        oracle_instance_id=oracle_instance_id,\n        module_id=module_id,\n        module_name=module_name,\n        operation=operation,\n        passed=passed,\n        input_count=result_input_count,\n        output_count=len(normalized_records),\n        records=normalized_records,\n        criteria=normalized_criteria,\n        decisions=normalized_decisions,\n        metrics=normalized_metrics,\n        insights=normalized_insights,\n        result_hash=result_hash,\n        read_only_guardrails=dict(READ_ONLY_GUARDRAILS),\n        telemetry=telemetry,\n        explainability={\n            "purpose": "Return canonical replay subsystem output.",\n            "contract": "ReplayResult",\n            "read_only_reason": "Replay subsystem operations derive views and intelligence only; they do not mutate markets or execute.",\n            "execution_boundary": "Q Series remains the only execution engine.",\n            **safe_dict(explainability),\n        },\n    )\n', encoding='utf-8')
